"""
AgentOS – Celery application factory.

All workers share this Celery instance.  Credentials are read exclusively from
settings (environment variables); nothing is hard-coded here.
"""

from __future__ import annotations

from celery import Celery
from celery.signals import worker_ready, worker_shutting_down

from core.config import settings
from core.logging_config import configure_logging, get_logger

logger = get_logger(__name__)


def create_celery_app() -> Celery:
    if not settings.task_queue_enabled:
        raise RuntimeError(
            "Celery is not configured. Set CELERY_BROKER_URL and "
            "CELERY_RESULT_BACKEND before scheduling background tasks."
        )
    app = Celery(
        "agentos",
        broker=settings.CELERY_BROKER_URL,
        backend=settings.CELERY_RESULT_BACKEND,
        include=[
            "services.orchestrator.tasks",
        ],
    )

    app.conf.update(
        task_serializer="json",
        accept_content=["json"],
        result_serializer="json",
        timezone="UTC",
        enable_utc=True,
        task_track_started=True,
        task_acks_late=True,
        task_reject_on_worker_lost=True,
        worker_prefetch_multiplier=settings.CELERY_WORKER_PREFETCH_MULTIPLIER,
        worker_max_tasks_per_child=settings.CELERY_WORKER_MAX_TASKS_PER_CHILD,
        task_soft_time_limit=settings.CELERY_TASK_SOFT_TIME_LIMIT,
        task_time_limit=settings.CELERY_TASK_TIME_LIMIT,
        task_always_eager=settings.is_test,
        broker_connection_retry_on_startup=True,
        broker_transport_options={
            "visibility_timeout": settings.CELERY_TASK_TIME_LIMIT + 60,
        },
        # Per-queue concurrency configuration
        task_routes={
            "services.orchestrator.tasks.run_subtask_research": {
                "queue": "research"
            },
            "services.orchestrator.tasks.run_subtask_code_exec": {
                "queue": "code_exec"
            },
            "services.orchestrator.tasks.run_subtask_browser": {
                "queue": "browser"
            },
            "services.orchestrator.tasks.run_subtask_multimodal": {
                "queue": "multimodal"
            },
            "services.orchestrator.tasks.run_subtask_verification": {
                "queue": "verification"
            },
            "services.orchestrator.tasks.run_subtask_synthesis": {
                "queue": "synthesis"
            },
            "services.orchestrator.tasks.run_subtask_default": {
                "queue": "default"
            },
        },
    )

    return app


celery_app: Celery | None = (
    create_celery_app() if settings.task_queue_enabled else None
)


@worker_ready.connect
def on_worker_ready(sender, **kwargs):
    configure_logging(log_level=settings.APP_LOG_LEVEL, json_logs=settings.is_production)
    logger.info("Celery worker ready", hostname=sender.hostname)


@worker_shutting_down.connect
def on_worker_shutting_down(sender, **kwargs):
    logger.info("Celery worker shutting down", hostname=sender.hostname)

