def _resolve_worker_hostname(sender, **kwargs) -> str:
    hostname = getattr(sender, "hostname", None)
    if isinstance(hostname, str) and hostname:
        return hostname
    if isinstance(sender, str) and sender:
        return sender
    for key in ("hostname", "worker_hostname"):
        value = kwargs.get(key)
        if isinstance(value, str) and value:
            return value
    instance = kwargs.get("instance")
    instance_hostname = getattr(instance, "hostname", None)
    if isinstance(instance_hostname, str) and instance_hostname:
        return instance_hostname
    return "unknown"


def _broker_transport_options() -> dict[str, int]:
    task_time_limit = settings.CELERY_TASK_TIME_LIMIT
    if isinstance(task_time_limit, int) and task_time_limit > 0:
        return {"visibility_timeout": task_time_limit + 60}
    return {}


